4. Удалите старую таблицу и переименуйте новую:
DROP TABLE orders;
ALTER TABLE orders_partitioned RENAME TO orders;

5. Обновите статистику:
VACUUM ANALYZE orders;

CREATE OR REPLACE FUNCTION vacuum_analyze_orders()
RETURNS TRIGGER AS $$
BEGIN
    PERFORM VACUUM ANALYZE orders;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER vacuum_analyze_orders_trigger
AFTER DELETE ON orders
FOR EACH STATEMENT
EXECUTE FUNCTION vacuum_analyze_orders();

DO $$
  DECLARE
    r RECORD;
  BEGIN
    FOR r IN 1..1000 LOOP
      DELETE FROM users WHERE is_active = false LIMIT 100;
      COMMIT;
      PERFORM pg_sleep_for('100ms');
    END LOOP;
  END
$$;

CREATE TABLE users_partitioned (LIKE users INCLUDING ALL)
PARTITION BY LIST (is_active);

CREATE TABLE users_active PARTITION OF users_partitioned FOR VALUES IN (true);
CREATE TABLE users_inactive PARTITION OF users_partitioned FOR VALUES IN (false);

INSERT INTO users_partitioned SELECT * FROM users;
DROP TABLE users;
ALTER TABLE users_partitioned RENAME TO users;

